+/* Buttons */
+.btn {
+    padding: 0.5rem 1rem;
+    border: none;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: all 0.15s ease;
+}
+
+.btn-primary {
+    background: var(--primary-color, #0d6efd);
+    color: white;
+}
+
+.btn-primary:hover {
+    background: #0b5ed7;
+}
+
+.btn-secondary {
+    background: var(--secondary-bg, #e9ecef);
+    color: var(--text-primary, #212529);
+}
+
+.btn-secondary:hover {
+    background: #d3d8dd;
+}
+
+.btn-danger {
+    background: #dc3545;
+    color: white;
+}
+
+.btn-danger:hover {
+    background: #bb2d3b;
+}
+
+.btn-sm {
+    padding: 0.3rem 0.6rem;
+    font-size: 0.8rem;
+}
+
+.form-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+/* Toggle Switches */
+.toggle-group {
+    margin-bottom: 1rem;
+}
+
+.toggle-label {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    cursor: pointer;
+}
+
+.toggle-input {
+    width: 2.5rem;
+    height: 1.3rem;
+    appearance: none;
+    background: #ccc;
+    border-radius: 1rem;
+    position: relative;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.toggle-input:checked {
+    background: var(--primary-color, #0d6efd);
+}
+
+.toggle-input::before {
+    content: '';
+    position: absolute;
+    width: 1rem;
+    height: 1rem;
+    border-radius: 50%;
+    background: white;
+    top: 0.15rem;
+    left: 0.15rem;
+    transition: transform 0.2s;
+}
+
+.toggle-input:checked::before {
+    transform: translateX(1.2rem);
+}
+
+/* Toast */
+.toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    animation: slideIn 0.3s ease;
+}
+
+.toast-success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+@keyframes slideIn {
+    from { opacity: 0; transform: translateY(-10px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+
+/* Profile Section */
+.avatar-area {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: var(--card-bg, #f8f9fa);
+    border-radius: 8px;
+}
+
+.avatar-preview {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    overflow: hidden;
+    border: 2px solid var(--border-color, #dee2e6);
+    flex-shrink: 0;
+}
+
+.avatar-image {
+    width: 100%;
+    height: 100%;
+    object-fit: cover;
+}
+
+.avatar-placeholder {
+    width: 100%;
+    height: 100%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    background: #e9ecef;
+    color: #6c757d;
+    font-size: 0.75rem;
+}
+
+.avatar-url-display {
+    font-size: 0.85rem;
+    color: var(--text-secondary, #6c757d);
+    word-break: break-all;
+}
+
+/* Notifications Section */
+.muted-channels {
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid var(--border-color, #dee2e6);
+}
+
+.muted-channels h3 {
+    margin-bottom: 0.75rem;
+    font-size: 1.1rem;
+}
+
+.channel-list {
+    list-style: none;
+    padding: 0;
+    margin: 0;
+}
+
+.channel-item {
+    padding: 0.5rem 0;
+}
+
+.channel-item label {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+}
+
+/* Security Section */
+.expandable-panel {
+    border: 1px solid var(--border-color, #dee2e6);
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 1rem 1.25rem;
+    background: var(--card-bg, #f8f9fa);
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid var(--border-color, #dee2e6);
+}
+
+.security-card {
+    padding: 1.25rem;
+    border: 1px solid var(--border-color, #dee2e6);
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+}
+
+.tfa-section {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.tfa-info {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.tfa-info h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.status-indicator {
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-size: 0.8rem;
+    font-weight: 500;
+}
+
+.status-enabled {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.status-disabled {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-section h3 {
+    margin-bottom: 1rem;
+    font-size: 1.1rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid var(--border-color, #dee2e6);
+}
+
+.sessions-table th {
+    font-weight: 600;
+    background: var(--card-bg, #f8f9fa);
+}
+
+.badge {
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-size: 0.75rem;
+    font-weight: 500;
+}
+
+.badge-current {
+    background: #cff4fc;
+    color: #055160;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    border-radius: 12px;
+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.dialog h3 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+    justify-content: flex-end;
+}
+
+/* Appearance Section */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Live Preview */
+.preview-area {
+    margin-top: 2rem;
+    padding: 1.5rem;
+    border: 1px solid var(--border-color, #dee2e6);
+    border-radius: 8px;
+    transition: all 0.3s ease;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 1rem;
+    font-size: 0.9rem;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    color: var(--text-secondary, #6c757d);
+}
+
+.preview-content {
+    transition: all 0.3s ease;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 1rem;
+    border: 1px solid var(--border-color, #dee2e6);
+    border-radius: 6px;
+}
+
+/* Preview Theme Variants */
+.preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-card {
+    border-color: #555;
+    background: #2a2a3e;
+}
+
+.preview-theme-system {
+    background: #f8f9fa;
+    color: #212529;
+}
+
+/* Preview Font Sizes */
+.preview-font-small .preview-text {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium .preview-text {
+    font-size: 1rem;
+}
+
+.preview-font-large .preview-text {
+    font-size: 1.2rem;
+}
+
+/* Compact Mode Preview */
+.preview-compact .preview-content {
+    line-height: 1.2;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.4rem;
+}
+
+/* Utilities */
+.text-muted {
+    color: var(--text-secondary, #6c757d);
+    font-size: 0.875rem;
+}
+
+.error-message {
+    color: #dc3545;
+    font-size: 0.875rem;
+    margin-bottom: 0.75rem;
+}
+
+.loading {
+    color: var(--text-secondary, #6c757d);
+    font-style: italic;
+}
+

